function putAfter(anchor,items){const i=slides.findIndex(x=>x.id===anchor);if(i<0)throw Error('No se encontró escena '+anchor);slides.splice(i+1,0,...items)}
putAfter('portada',[
exSlide('sobre-mi','01 · Introducción','Marco Mayta','Director de investigación · QPerú | PhD Student · ICMC–USP | QIntern 2026 · QWorld',`<div class="about-grid"><div class="photo-block"><img src="${IMAGES['foto_marco_nueva.jpg']}" class="speaker-photo" alt="Marco Mayta"></div><div>${para('<strong>Doctorando directo en Ciencias de la Computación</strong> en el Instituto de Ciencias Matemáticas y de Computación de la Universidad de São Paulo (ICMC–USP). Egresado de Ingeniería Estadística e Informática de la <strong>Universidad Nacional del Altiplano</strong>.','<strong>Director de investigación de QPerú</strong> y participante como <strong>Research Intern en QIntern 2026 de QWorld</strong>.')}${inside('<strong>Intereses de investigación:</strong> optimización y compilación de circuitos cuánticos, aprendizaje automático y métodos reproducibles.')}<div class="speaker-contacts"><a href="https://orcid.org/0009-0009-6019-2925" target="_blank" rel="noopener noreferrer"><span>ORCID</span><strong>0009-0009-6019-2925 ↗</strong></a><a href="https://www.linkedin.com/in/marco-mayta-835781170/" target="_blank" rel="noopener noreferrer"><span>LinkedIn</span><strong>Marco Mayta ↗</strong></a><a href="https://github.com/marcofmayta" target="_blank" rel="noopener noreferrer"><span>GitHub</span><strong>@marcofmayta ↗</strong></a><a href="mailto:marcomayta24@usp.br"><span>USP · Correo institucional</span><strong>marcomayta24@usp.br</strong></a><a href="mailto:marco.mayta@qperu.net"><span>QPerú · Correo de miembro</span><strong>marco.mayta@qperu.net</strong></a></div><div class="footnote">Perú · Brasil · Investigación y formación científica</div></div></div>`,true),
exSlide('qintern','01 · Introducción','QTagger+ · QIntern 2026','Mi experiencia como Research Intern en QIntern 2026.',split(`<div class="pill">QWorld · QIntern 2026 · Proyecto de equipo</div><div class="prose" style="margin-top:18px"><p><strong>QTagger+</strong> exploró métodos cuántico-clásicos para problemas de clasificación en ciberseguridad y experimentos con generación de datos sintéticos.</p><p>El trabajo incluyó implementación de modelos, comparación de métodos y documentación de experimentos.</p></div><div class="qtagger-flow"><span>Datos</span> → <span>Modelos clásicos / híbridos</span> → <span>Evaluación</span></div>`,panel('Trabajo de investigación',`<div class="numbered"><span class="n">01</span><div>Definir una tarea y criterios de evaluación.</div></div><div class="numbered"><span class="n">02</span><div>Comparar con modelos clásicos bajo las mismas condiciones.</div></div><div class="numbered"><span class="n">03</span><div>Evaluar el desempeño y las limitaciones de cada método.</div></div><div class="footnote">Proyecto de equipo · QIntern 2026 · QWorld</div>`),'wide-left'),true),
]);
putAfter('sobre-mi',[
exSlide('qworld-qperu','01 · Introducción','QWorld y QPerú: aprender en comunidad','De una red global a la comunidad cuántica peruana.',split(panel('QWorld · Red global',`<img class="community-logo" src="${IMAGES['qworld-logo.jpg']}" alt="QWorld"><div class="prose"><p>Organización global sin fines de lucro que conecta educación, desarrollo e investigación en tecnologías cuánticas.</p><p><strong>QIntern</strong> reúne participantes y mentores para desarrollar proyectos de investigación, software y materiales educativos.</p></div>${source('QWorld · QIntern','https://qworld.net/qintern-2026/')}`),panel('QPerú · Comunidad local',`<img class="community-logo" src="${IMAGES['qperu-logo.svg']}" alt="QPerú"><div class="prose"><p>Comunidad peruana que impulsa educación, investigación y colaboración en computación cuántica.</p><p>Busca integrarse como capítulo de la red <strong>QWorld</strong>.</p></div>${source('QPerú · Presentación de la comunidad','https://github.com/QPeru/QPeru')}`)),true)
]);
putAfter('dos',[
exSlide('puente-estadistica','01 · Introducción','¿Qué tiene que ver esto con Estadística e Informática?','Los circuitos pueden estudiarse con herramientas que ya conocemos.',split(panel('Estadística',`<div class="lead">Probabilidad, muestreo, estimación y error</div><div class="prose"><p>Las mediciones de un qubit producen frecuencias. Evaluaremos cómo fluctúan y qué se puede inferir a partir de ellas.</p></div>`),panel('Informática',`<div class="lead">Algoritmos, grafos, compilación y complejidad</div><div class="prose"><p>Los circuitos son programas. Deben traducirse a instrucciones compatibles con las conexiones y puertas de un dispositivo.</p></div>`)),true)
]);
putAfter('qubit',[
exSlide('qubit-estado-derivacion','02 · Bits y qubits','El estado de un qubit, paso a paso','Dos amplitudes complejas describen un estado puro en la base computacional.',split(`${inside('<div class="math">|ψ⟩ = α|0⟩ + β|1⟩</div>')}<div class="eq-flow"><div><b>1.</b> Elegimos una base: |0⟩ y |1⟩.</div><div><b>2.</b> α y β son <em>amplitudes</em>, no probabilidades.</div><div><b>3.</b> Al medir: P(0) = |α|² y P(1) = |β|².</div><div><b>4.</b> Las probabilidades suman uno.</div></div>`,panel('La condición de normalización',`<div class="math">|α|² + |β|² = 1</div><div class="prose"><p>Ejemplo: α = 3/5 y β = 4/5.</p><p>P(0) = 9/25 = 36 %<br>P(1) = 16/25 = 64 %.</p></div>${source('IBM Quantum Learning · Single systems','https://quantum.cloud.ibm.com/learning')}`)),true),
exSlide('amplitudes-cambiar','02 · Bits y qubits','Laboratorio: de amplitudes a probabilidades','Modifica una amplitud real; la otra se ajusta para mantener la normalización.',()=>split(`${R('Amplitud α',0,1,.05,'alphaDemo',v=>v.toFixed(2))}${inside('<div class="math">β = √(1 − α²)</div>')}<div class="small muted">Este ejemplo utiliza amplitudes reales no negativas.</div>`,panel('Probabilidades resultantes',`<div id="lab-result"></div>`),'wide-left'),true),
exSlide('complejas','02 · Bits y qubits','Las amplitudes también pueden ser complejas','La fase relativa contiene información que no aparece en una medición directa en Z.',split(`${inside('<div class="math">|ψ⟩ = cos(θ/2)|0⟩ + e<sup>iφ</sup> sin(θ/2)|1⟩</div>')}<div class="prose"><p><strong>θ</strong> controla la proporción de las amplitudes.<br><strong>φ</strong> controla su fase relativa.</p><p>Para un qubit puro, θ ∈ [0, π] y φ ∈ [0, 2π).</p></div>`,panel('Una diferencia esencial',`<div class="math">|+⟩ = (|0⟩ + |1⟩)/√2<br>|−⟩ = (|0⟩ − |1⟩)/√2</div><div class="prose"><p>Ambos producen 50 % / 50 % al medirse en Z. Sin embargo, reaccionan de forma distinta a otra puerta H.</p></div>`)),false),
]);
putAfter('phase',[
exSlide('fase-formula','02 · Bits y qubits','¿Dónde se observa la fase relativa?','Cambiamos la base antes de medir: la interferencia modifica las probabilidades.',()=>split(`${inside('<div class="math">|ψ<sub>φ</sub>⟩ = (|0⟩ + e<sup>iφ</sup>|1⟩)/√2</div>')}<div class="math" style="margin:18px 0">P(+) = (1 + cos φ) / 2</div>${R('Fase φ',0,360,15,'phaseDemo',v=>v+'°')}<div class="small muted">Las mediciones en Z siguen dando 50 % / 50 %.</div>`,panel('Medición en la base X',`<div id="lab-result"></div>`),'wide-left'),true),
exSlide('fase-ejercicio','02 · Bits y qubits','Ejercicio: misma probabilidad, distinto estado','Imaginemos que medimos |+⟩ y |−⟩ después de aplicar H.',()=>Q('faseej','¿Qué resultado esperamos al medir H|−⟩ en la base Z?',['Siempre 0','Siempre 1','0 y 1 con 50 %'],1,'H|−⟩ = |1⟩. La fase relativa se convierte en una diferencia visible en la medición.'),true),
]);
putAfter('born',[
exSlide('binomial','02 · Bits y qubits','Del qubit a la distribución binomial','Cuando repetimos una medición ideal, las frecuencias son aleatorias.',split(`${inside('<div class="math">X ∼ Binomial(n, p)</div>')}<div class="eq-flow"><div><b>n:</b> número de mediciones (*shots*).</div><div><b>p:</b> probabilidad teórica del resultado.</div><div><b>X:</b> veces que aparece el resultado.</div><div><b>p̂ = X/n:</b> frecuencia relativa observada.</div></div>`,panel('Variabilidad de la estimación',`<div class="math">SE(p̂) = √[p(1−p)/n]</div><div class="prose"><p>Con p = 0,5 y n = 1024:</p><p><strong>SE ≈ 0,0156</strong> (1,56 puntos porcentuales).</p><p>Esto no es ruido del hardware.</p></div>`)),true),
exSlide('intervalo','02 · Bits y qubits','¿Cuántos shots necesitamos?','Un intervalo aproximado ilustra cómo mejora la precisión al repetir.',()=>split(`${R('Shots',64,8192,64,'varianceN',v=>v.toLocaleString('es-PE'))}${inside('<div class="math">Margen ≈ 1,96 × √[0,25/n]</div>')}<div class="small muted">Aproximación normal para p = 0,5; no es un intervalo universal.</div>`,panel('Margen alrededor de 50 %',`<div id="lab-result"></div>`),'wide-left'),true),
]);
putAfter('vec',[
exSlide('producto-tensor','02 · Bits y qubits','Cuando hay dos qubits','El espacio conjunto tiene cuatro estados base.',split(`${inside('<div class="math">|a⟩ ⊗ |b⟩ = |ab⟩</div>')}<div class="prose"><p>La base de dos qubits es |00⟩, |01⟩, |10⟩, |11⟩.</p><p>Un estado genérico necesita cuatro amplitudes complejas normalizadas.</p></div><div class="math" style="font-size:24px">|ψ⟩ = a₀₀|00⟩ + a₀₁|01⟩ + a₁₀|10⟩ + a₁₁|11⟩</div>`,panel('Ejemplo',`<div class="math">|+⟩ ⊗ |0⟩ = (|00⟩ + |10⟩)/√2</div><div class="prose"><p>Es una superposición de dos estados conjuntos, pero <strong>no está entrelazado</strong>: se puede factorizar como producto.</p></div>`)),true),
exSlide('producto-interactivo','02 · Bits y qubits','Ejercicio: forma un estado de dos qubits','Elige el estado de cada qubit y calcula su producto tensorial.',()=>split(`<div class="select-line">Qubit A: ${['0','1','+'].map(s=>B('|'+s+'⟩','tensorA',s,st.tensorA===s)).join('')}</div><div class="select-line">Qubit B: ${['0','1','+'].map(s=>B('|'+s+'⟩','tensorB',s,st.tensorB===s)).join('')}</div><div class="prose"><p>Multiplica cada amplitud de A por cada amplitud de B.</p></div>`,panel('Estado conjunto',`<div id="lab-result"></div>`),'wide-left'),true),
]);
putAfter('circuito',[
exSlide('unitarias','03 · Circuitos','Las puertas son matrices unitarias','Conservan la norma del estado y permiten invertir la transformación.',split(`${inside('<div class="math">U†U = I</div>')}<div class="prose"><p>Una operación unitaria transforma amplitudes sin destruir la normalización.</p><p>La medición, en cambio, produce un resultado clásico y cambia el estado condicionado al resultado.</p></div>`,panel('Tres matrices fundamentales',`<div class="matrix-show"><div><strong>X</strong><br>⎡0 1⎤<br>⎣1 0⎦</div><div><strong>Z</strong><br>⎡1 0⎤<br>⎣0 −1⎦</div><div><strong>H</strong><br>1/√2 ×<br>⎡1  1⎤<br>⎣1 −1⎦</div></div>`)),true),
exSlide('matrices-prueba','03 · Circuitos','Demostración: H aplicada dos veces','Multiplicar las matrices revela por qué H² = I.',split(`${inside('<div class="math">H² = ½ [1  1; 1 −1] [1  1; 1 −1]</div>')}<div class="eq-flow"><div>Entrada superior izquierda: 1×1 + 1×1 = 2.</div><div>Superior derecha: 1×1 + 1×(−1) = 0.</div><div>Inferior izquierda: 1×1 + (−1)×1 = 0.</div><div>Inferior derecha: 1×1 + (−1)² = 2.</div></div>`,panel('Resultado',`<div class="math">H² = ½ [2 0; 0 2] = I</div><div class="prose"><p>Aplicar H dos veces recupera cualquier estado inicial, no solo |0⟩.</p></div>`)),true),
]);
putAfter('puertas',[
exSlide('matriz-taller','03 · Circuitos','Laboratorio: compón puertas','Construye una secuencia y mira cómo cambia el estado |0⟩.',()=>split(`<div class="choice-row">${['H','X','Z'].map(g=>B(g,'work-gate',g)).join('')}${B('Deshacer','work-undo','')}${B('Restablecer','work-clear','')}</div><div class="prose"><p>Intenta formar <strong>H → Z → H</strong>. ¿Se parece a alguna puerta conocida?</p></div>`,panel('Estado y secuencia',`<div id="lab-result"></div>`),'wide-left'),true)
]);
putAfter('cx',[
exSlide('cx-linealidad','03 · Circuitos','CX también actúa sobre superposiciones','Una puerta controlada no mide al qubit de control.',split(`${inside('<div class="math">CX(|0⟩⊗|0⟩) = |00⟩</div>')}${inside('<div class="math">CX(|1⟩⊗|0⟩) = |11⟩</div>')}<div class="prose"><p>Si la entrada es una suma de estados, aplicamos CX a cada término por linealidad.</p></div>`,panel('Ejemplo',`<div class="math">CX[(|00⟩+|10⟩)/√2]</div><div class="math">= (|00⟩+|11⟩)/√2</div><div class="prose"><p>La correlación surge de transformar el estado conjunto.</p></div>`)),true)
]);
putAfter('bell-estado',[
exSlide('bell-demostracion','03 · Circuitos','Demostración completa del estado de Bell','Partimos de |00⟩ y aplicamos dos operaciones.',split(`<div class="eq-flow"><div><b>Estado inicial</b><div class="math">|ψ₀⟩ = |00⟩</div></div><div><b>Hadamard sobre q₀</b><div class="math">|ψ₁⟩ = (|00⟩+|10⟩)/√2</div></div><div><b>CX con q₀ como control</b><div class="math">|ψ₂⟩ = (|00⟩+|11⟩)/√2</div></div></div>`,panel('Predicción',`${bars([['00',.5],['01',0],['10',0],['11',.5]])}<div class="prose"><p>Solo veremos 00 y 11 al medir en Z. No estamos midiendo el estado durante la aplicación de las puertas.</p></div>`)),true)
]);
putAfter('bell-correl',[
exSlide('bell-test','03 · Circuitos','¿Cómo distinguimos Bell de una mezcla clásica?','En la base Z pueden verse iguales; en la base X no.',()=>split(`<div class="choice-row">${B('Estado de Bell','bell-model','puro',st.modelBell==='puro')}${B('Mezcla clásica','bell-model','mezcla',st.modelBell==='mezcla')}</div><div class="select-line">Base: ${B('Z','bellbasis','Z',st.bellBasis==='Z')}${B('X','bellbasis','X',st.bellBasis==='X')}</div>`,panel('Probabilidades de las mediciones',`<div id="lab-result"></div><div class="footnote">Modelo ideal, sin ruido; medir en X equivale a aplicar H antes de medir en Z.</div>`),'wide-left'),true),
exSlide('entrelazamiento-ejercicio','03 · Circuitos','Ejercicio: ¿entrelazado o separable?','Una superposición por sí sola no implica entrelazamiento.',()=>Q('entrelazado','¿Cuál de estos estados no puede factorizarse como producto de dos estados de un qubit?',['(|00⟩+|10⟩)/√2','(|00⟩+|11⟩)/√2','|0⟩⊗|+⟩'],1,'El estado de Bell no puede escribirse como |a⟩⊗|b⟩. Los otros dos son productos de estados individuales.'),true)
]);
putAfter('qiskit',[
exSlide('qiskit-objetos','04 · Qiskit','Cómo se organiza un experimento con Qiskit','No hace falta memorizar Python: conviene entender cuatro objetos.',split(`<div class="eq-flow"><div><b>QuantumCircuit</b>: representa las operaciones.</div><div><b>Puertas</b>: H, X, CX y medición.</div><div><b>StatevectorSampler</b>: obtiene muestras de un circuito ideal.</div><div><b>Counts</b>: agrupa los resultados obtenidos.</div></div>`,panel('Fragmento mínimo',`<pre class="qcode">qc = QuantumCircuit(2)\nqc.h(0)\nqc.cx(0, 1)\nqc.measure_all()</pre><div class="footnote">Ejemplo para simulación. La ejecución en hardware requiere pasos adicionales.</div>`)),true),
exSlide('shots-ejercicio','04 · Qiskit','Ejercicio: de probabilidades a conteos','Con 1024 shots, ¿cuántas veces esperamos observar 11 en Bell?',()=>Q('conteos','La probabilidad teórica de 11 es 0,5. ¿Cuál es el conteo esperado?', ['256', '512', '1024'],1,'E[X] = np = 1024×0,5 = 512. El conteo observado puede diferir debido al muestreo.'),true),
]);
putAfter('shots',[
exSlide('shots-contraste','04 · Qiskit','Estimación, sesgo y variabilidad','Una muestra no identifica por sí sola el valor de la probabilidad.',split(`${inside('<div class="math">p̂ = X/n</div>')}<div class="prose"><p>Si medimos 530 veces el estado 11 en 1024 shots, la estimación es <strong>530/1024 ≈ 0,5176</strong>.</p><p>El estado ideal predice 0,5. La diferencia puede explicarse por azar, sin necesidad de introducir ruido físico.</p></div>`,panel('Tres conceptos distintos',`<div class="prose"><p><b>Estimación:</b> frecuencia de la muestra.</p><p><b>Variabilidad:</b> diferencia entre repeticiones.</p><p><b>Ruido:</b> desviaciones debidas al dispositivo o al modelo físico.</p></div>`)),false)
]);
